{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello डॉक्टर जी आपको painting contractors की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "Hello."
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "नमस्ते।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "आपको painting contractors की requirement थी ना?"
    },
    {
      "i": 4,
      "speaker": "caller",
      "text": "Yes."
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "हाँ जी बताइए।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "आपको कितने square feet का काम करवाना है?"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "मुझे exterior पे करवाना है।"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "और ये पड़ जाएगा आपका कम से कम।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "पर आपने quantity नहीं बताई आपको कितने square feet का काम करवाना है?"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "कृपया बता दीजिए।"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "सात सात सात सौ आठ सौ square feet area होगा।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "अब service scope की बात करते हैं।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "आपको exterior काम करवाना है या interior या कुछ और?"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "exterior."
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "अब बताइए paint type में क्या prefer करेंगे?"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "texture paint, PU paint या कोई और?"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "ये आपका exterior पे जो paint होता है वही वाला।"
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "मैं समझ गई पर क्या आप इनमें से कोई specific option जैसे texture या PU paint चुनना चाहेंगे या कुछ और?"
    },
    {
      "i": 23,
      "speaker": "caller",
      "text": "नहीं ma'am simple जो जो बारिश में खराब नहीं होता वो कौन सा होगा आप guide करे ना।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "बारिश के लिए texture या PU paint अच्छे रहते हैं?"
    },
    {
      "i": 25,
      "speaker": "bot",
      "text": "आप इनमें से क्या prefer करेंगे या फिर seller से discuss करना चाहेंगे?"
    },
    {
      "i": 26,
      "speaker": "caller",
      "text": "ये seller से discuss करना चाहूंगी मैं अभी ना।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "ठीक है seller आपकी इस detail में मदद कर देंगे।"
    },
    {
      "i": 28,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 29,
      "speaker": "caller",
      "text": "ठीक है done."
    }
  ]
}
